INSERT INTO retros (code, name, phase, created_at, demo) VALUES ('ACME01', 'Retro del Q3 · Experiencia Cliente de ACME', 4, '2026-10-01T09:00:00.000Z', 1);
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00001', 'ACME01', 1, 'proceso', 'Pasamos a la herramienta nueva de tickets en la tercera semana del trimestre.', 1, '2026-10-01T09:01:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00002', 'ACME01', 1, 'proceso', 'El tiempo de primera respuesta bajó de 9 horas a 3 horas.', 2, '2026-10-01T09:02:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00003', 'ACME01', 1, 'producto', 'Los reembolsos subieron un 40% y tardan 6 días en promedio en resolverse.', 2, '2026-10-01T09:03:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00004', 'ACME01', 1, 'producto', 'El lanzamiento de la línea de taladros trajo 320 consultas en 48 horas.', 1, '2026-10-01T09:04:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00005', 'ACME01', 1, 'equipo', 'Cuatro personas cubrieron guardias de fin de semana durante el lanzamiento.', 1, '2026-10-01T09:05:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00006', 'ACME01', 1, 'producto', 'La satisfacción de quienes nos escriben se mantuvo en 4,5 sobre 5.', 0, '2026-10-01T09:06:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00007', 'ACME01', 2, 'proceso', 'La herramienta nueva ordena la cola, pero las etiquetas automáticas mandan mal los pedidos de reembolso.', 3, '2026-10-01T09:07:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00008', 'ACME01', 2, 'equipo', 'Respondemos rápido, pero a veces sin resolver: la persona vuelve a escribir y hay que empezar de cero.', 2, '2026-10-01T09:08:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00009', 'ACME01', 2, 'producto', 'El lanzamiento nos encontró sin guía de respuestas ni stock visible para el equipo.', 2, '2026-10-01T09:09:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00010', 'ACME01', 2, 'equipo', 'Nos pone orgullosos cómo nos cubrimos entre todos esa semana.', 3, '2026-10-01T09:10:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00011', 'ACME01', 3, 'proceso', 'Los reembolsos pasan por tres personas y nadie ve en qué paso está cada uno.', 9, '2026-10-01T09:11:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00012', 'ACME01', 3, 'equipo', 'Cansancio acumulado: las guardias las hicimos siempre las mismas cuatro personas.', 7, '2026-10-01T09:12:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00013', 'ACME01', 3, 'producto', 'Faltan avisos de stock y fechas de lanzamiento antes de que lleguen las consultas.', 6, '2026-10-01T09:13:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00014', 'ACME01', 3, 'proceso', 'Las etiquetas automáticas siguen clasificando mal y nadie las revisa.', 5, '2026-10-01T09:14:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00015', 'ACME01', 3, 'equipo', 'Cuesta pedir ayuda cuando la cola está llena.', 4, '2026-10-01T09:15:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00016', 'ACME01', 4, 'proceso', 'Experimento 1, tablero de reembolsos: Diego y Lucía arman un tablero con el paso de cada reembolso y lo repasan en la daily. Hasta el 28 de noviembre. Sabremos que funcionó si el tiempo promedio baja de 6 a 3 días.', 3, '2026-10-01T09:16:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00017', 'ACME01', 4, 'equipo', 'Experimento 2, rotación de guardias: Marta arma un calendario rotativo con las 8 personas. Hasta el 15 de diciembre. Sabremos que funcionó si nadie hace más de una guardia por mes y el cansancio baja en la próxima retro.', 3, '2026-10-01T09:17:00.000Z');
INSERT INTO items (id, code, phase, lens, text, votes, at) VALUES ('ACME00018', 'ACME01', 4, 'producto', 'Experimento 3, aviso de lanzamientos: Valeria pide a Producto una nota 5 días antes de cada lanzamiento, con stock y preguntas frecuentes. Hasta el lanzamiento de enero. Sabremos que funcionó si las consultas repetidas de las primeras 48 horas bajan un 30%.', 2, '2026-10-01T09:18:00.000Z');
